materials.fragmentShader:
uniform vec3 uColor; uniform float uOp, uT; varying float vS; varying float vU; varying vec3 vW;
void main(){
  /* derivative normals degenerate on quads straddling the floor seam: guard, or NaN blows up white in bloom */
  vec3 c = cross(dFdx(vW), dFdy(vW));
  float l = length(c);
  float f = l > 1e-10 ? abs(dot(c / l, normalize(cameraPosition - vW))) : 0.0;
  float drift = 0.88 + 0.12 * sin(vW.z * 1.3 + uT * 0.16) * sin(vW.y * 2.1 - uT * 0.1);
  /* r1: the alphaFalloff('shaft') edge ramp (20 % in from each side) across the opening's width, so the prism's
     flanks and long edges fade out instead of cutting a hard triangle into the hall */
  float edge = smoothstep(0.0, 0.2, vU) * (1.0 - smoothstep(0.8, 1.0, vU)); /* GLSL: edge0 < edge1 */
  float a = uOp * pow(1.0 - vS, 1.15) * pow(f, 1.4) * drift * edge;
  gl_FragColor = vec4(uColor, clamp(a, 0.0, 1.0));
}

materials.vertexShader:
uniform float uTime, uSize, uScale;
uniform vec3 uBox0, uBoxSize, uFocus; uniform float uFocusR;
attribute vec4 aSeed;
varying float vA;
void main(){
  vec3 p = uBox0 + uBoxSize * aSeed.xyz;
  float t = uTime * (0.012 + aSeed.w * 0.016); /* slow drift: fast specks read as flicker */
  p += vec3(sin(t * 3.1 + aSeed.w * 40.0), sin(t * 2.3 + aSeed.x * 31.0) * 0.6 + t * 0.1, cos(t * 2.7 + aSeed.y * 27.0)) * 0.18;
  p = uBox0 + mod(p - uBox0, uBoxSize);
  vec4 mv = modelViewMatrix * vec4(p, 1.0);
  gl_Position = projectionMatrix * mv;
  float tw = 0.8 + 0.2 * sin(uTime * 0.07 + aSeed.z * 20.0); /* no twinkle: brightness stays steady */
  float f = uFocusR > 0.0 ? 1.0 - smoothstep(0.0, uFocusR, distance(p, uFocus)) : 1.0;
  vA = tw * f * (0.4 + 0.6 * aSeed.w);
  gl_PointSize = clamp(uSize * uScale * (0.6 + aSeed.w * 0.8) / max(0.2, -mv.z), 1.0, 5.0);
}

materials.fragmentShader:
uniform vec3 uColor; uniform float uOpacity; varying float vA;
void main(){
  float d = length(gl_PointCoord - 0.5) * 2.0;
  float a = smoothstep(1.0, 0.0, d); a *= a;
  gl_FragColor = vec4(uColor, a * vA * uOpacity);
}

